INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l36',3,8,36,'A Chance in a Million','百万分之一的机遇','used to do 与 would(过去习惯)、accept 与 agree 的区别、所有格撇号(''s / s'' / 不规则复数 ''s / 时间·价值 s'')、After having been + 过去分词(完成被动分词)、was thought/presumed to have done(被认为已…)(原创承载 NCE3 L36 考点·净化换情节:去掉''战时阵亡/负伤/医院被炸/空袭''的战争外壳,改为兄弟当年在大洪水中失散、被冲到远方幸存、以为家人罹难而定居他乡;失散兄弟因巧合团聚的温情内核原样保留;美式化人名 Frank/Henry Bassett)','我们不像从前那么轻信了。在十九世纪,小说家常常靠给读者抛出一连串巧合来收尾——大多数巧合都离奇得不着边际。读者会心满意足地接受:一个不起眼的女仆其实是主人公的母亲;一个被认定已死的失散兄弟,其实一直好好活着,还心怀鬼胎地谋划着主人公的垮台。如今的读者会觉得这种幼稚的收场完全无法接受。可在现实里,种种情形有时偏偏凑到一起,促成一些除了十九世纪小说家、谁都会觉得难以置信的巧合。我小时候,祖父给我讲过:一位美国出租车司机弗兰克·巴塞特,找到了一个二十年前被认为已在一场大洪水中丧生的兄弟。一次,弗兰克和妻子徒步旅行,停下来跟一个干活的工人搭话。两人走开后,巴塞特太太说那工人和自己丈夫长得太像了,甚至猜他会不会就是弗兰克的兄弟。弗兰克对这个想法嗤之以鼻,说自己的兄弟早在那场洪水里没了。巴塞特太太虽然对这段往事了如指掌,却觉得自己说中的可能哪怕只有百万分之一。几天后,她派了个男孩去问那工人,他是不是叫亨利·巴塞特。不用说,那人正叫亨利·巴塞特,他真的就是弗兰克失散多年的兄弟。兄弟俩重逢时,亨利讲清了自己是怎么活下来的。当年被洪水远远冲到下游后,他被带到了一座遥远的小镇,在那里慢慢养好了身子,和所有熟人都断了联系。他徒步往家走,回到家却发现家里的房子早被洪水冲毁,街坊里也没人知道原来的住户去了哪儿。亨利以为家人都在洪水中淹死了,便在五十英里外的一个村子安顿下来,从此一直住在那里。','{"q":"Listen and answer — What was the chance in a million?","options":["That a workman turned out to be a long-lost brother","That Frank won a lottery","That the flood would come back","That the taxi would break down"],"answer_index":0}'::jsonb,'{"title":"used to / would / accept vs agree / 所有格撇号 / After having been + p.p. / was thought to have done","intro":"①used to do 表过去的习惯或状态(现在不再);would 也可表过去反复的动作(但不表状态)。②accept 是“接受(事实、东西、礼物)”,agree(with sb / to do)是“同意(看法、做法)”。③所有格:单数名词加 ''s(hero''s);不规则复数加 ''s(children''s);以 s 结尾的复数加 ''(soldiers'');时间/价值也用 ''s(in six hours'' time)。④After having been + 过去分词=“在被…之后”。⑤was thought/presumed/believed to have done=“被认为已经做过…”。","table":{"headers":["用法","意思","例子"],"rows":[["used to do / would","过去习惯","less credulous than we used to be"],["accept / agree","接受 / 同意","readers accepted the fact"],["''s / s'' / 不规则复数 ''s","所有格","the hero''s mother / children''s"],["After having been p.p. / was thought to have","被…之后 / 被认为已…","was thought to have died"]]},"specialRules":[{"rule":"所有格:单数 + ''s(a woman''s bag);复数以 s 结尾只加 ''(the soldiers'' uniforms);不规则复数 + ''s(the children''s clothes);时间价值 + ''s(in six hours'' time / a dollar''s worth)。","mark":"''s / s''"},{"rule":"After having been + 过去分词,表示“在被…之后”(完成被动分词):After having been wounded, he…。","mark":"After having been p.p."},{"rule":"美式:neighborhood(英式 neighbourhood)、apartment(英式 flat)、vacation(英式 holiday)。本课已按美语写。","mark":"neighborhood / apartment"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l36',1,NULL,'We are less credulous than we used to be. In the nineteenth century, a novelist would bring his story to a conclusion by presenting his readers with a series of coincidences, most of them wildly improbable. Readers happily accepted the fact that an obscure servant girl was really the hero''s mother, or that a long-lost brother, presumed dead, was really alive all the time and wickedly plotting the hero''s downfall.','我们不像从前那么轻信了。在十九世纪,小说家常常靠给读者抛出一连串巧合来收尾——大多数巧合都离奇得不着边际。读者会心满意足地接受:一个不起眼的女仆其实是主人公的母亲;一个被认定已死的失散兄弟,其实一直好好活着,还心怀鬼胎地谋划着主人公的垮台。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l36',2,NULL,'Modern readers would find such naive solutions totally unacceptable. Yet, in real life, circumstances do sometimes conspire to bring about coincidences that anyone but a nineteenth-century novelist would find incredible. When I was a boy, my grandfather told me how an American taxi driver, Frank Bassett, found a brother who was thought to have died in a great flood twenty years before.','如今的读者会觉得这种幼稚的收场完全无法接受。可在现实里,种种情形有时偏偏凑到一起,促成一些除了十九世纪小说家、谁都会觉得难以置信的巧合。我小时候,祖父给我讲过:一位美国出租车司机弗兰克·巴塞特,找到了一个二十年前被认为已在一场大洪水中丧生的兄弟。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l36',3,NULL,'While on a walking tour with his wife, Frank stopped to talk to a workman. After they had gone on, Mrs. Bassett commented on the workman''s close resemblance to her husband and even suggested that he might be his brother. Frank poured scorn on the idea, pointing out that his brother had been lost in the flood long ago.','一次,弗兰克和妻子徒步旅行,停下来跟一个干活的工人搭话。两人走开后,巴塞特太太说那工人和自己丈夫长得太像了,甚至猜他会不会就是弗兰克的兄弟。弗兰克对这个想法嗤之以鼻,说自己的兄弟早在那场洪水里没了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l36',4,NULL,'Though Mrs. Bassett knew the story well, she thought that there was a chance in a million that she might be right. A few days later, she sent a boy to the workman to ask him whether his name was Henry Bassett. Needless to say, the man''s name was Henry Bassett, and he really was Frank''s long-lost brother. When the brothers were reunited, Henry explained how it was that he was still alive.','巴塞特太太虽然对这段往事了如指掌,却觉得自己说中的可能哪怕只有百万分之一。几天后,她派了个男孩去问那工人,他是不是叫亨利·巴塞特。不用说,那人正叫亨利·巴塞特,他真的就是弗兰克失散多年的兄弟。兄弟俩重逢时,亨利讲清了自己是怎么活下来的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l36',5,NULL,'After having been swept far downstream by the floodwaters, he had been carried to a distant town and had slowly recovered there, cut off from everyone he knew. He had made his way home on foot, only to find that the family house had been washed away and that no one in the neighborhood knew what had become of the residents. Assuming that his family had drowned in the flood, Henry had settled down in a village fifty miles away, where he had remained ever since.','当年被洪水远远冲到下游后,他被带到了一座遥远的小镇,在那里慢慢养好了身子,和所有熟人都断了联系。他徒步往家走,回到家却发现家里的房子早被洪水冲毁,街坊里也没人知道原来的住户去了哪儿。亨利以为家人都在洪水中淹死了,便在五十英里外的一个村子安顿下来,从此一直住在那里。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
